#[inductive(combiner_send_skip)]
fn combiner_send_skip_inductive(pre: Self, post: Self) {
    // The transition only updates combiner.idx from j to j+1.
    // All other state (clients, slots, requests, responses) is unchanged.

    // Let j be the index from the transition
    let j = pre.combiner.get_Responding_idx();

    // In pre state, we have pre.combiner.elems[j] = None (from the transition requirement)
    assert(pre.combiner.get_Responding_elems().index(j as int) == Option::None);

    // Therefore, pre.combiner_has(j) is false
    assert(!pre.combiner_has(j));

    // For any i, since clients, slots, requests, responses are unchanged:
    assert(forall|i: nat| post.clients.index(i) == pre.clients.index(i));
    assert(forall|i: nat| post.slots.index(i) == pre.slots.index(i));
    assert(forall|i: nat| post.requests.index(i) == pre.requests.index(i));
    assert(forall|i: nat| post.responses.index(i) == pre.responses.index(i));

    // not_waiting_inv: If client is Idle, slot is false
    assert(forall|i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() ==>
        !post.slots.index(i)) by {
        assert forall|i: nat| #[trigger] post.valid_idx(i) && post.clients.index(i).is_Idle() implies
            !post.slots.index(i) by {
            assert(post.clients.index(i) == pre.clients.index(i));
            assert(post.slots.index(i) == pre.slots.index(i));
            assert(!pre.slots.index(i));
        }
    };

    // waiting_inv: If client is Waiting, it has request, response, or is in combiner_has
    assert(forall|i: nat| #[trigger] post.client_waiting(i) ==>
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i)) by {
        assert forall|i: nat| #[trigger] post.client_waiting(i) implies
            post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
            assert(post.client_waiting(i) == pre.client_waiting(i));
            assert(post.request_stored(i) == pre.request_stored(i));
            assert(post.response_stored(i) == pre.response_stored(i));

            if pre.client_waiting(i) {
                // From pre.waiting_inv
                assert(pre.request_stored(i) || pre.response_stored(i) || pre.combiner_has(i));

                if i == j {
                    // For i = j, pre.combiner_has(j) is false (we proved this above)
                    assert(!pre.combiner_has(j));
                    // So we must have pre.request_stored(j) || pre.response_stored(j)
                    assert(pre.request_stored(j) || pre.response_stored(j));
                    // And since these are unchanged:
                    assert(post.request_stored(j) || post.response_stored(j));
                    // And post.combiner_has(j) is false:
                    assert(!post.combiner_has(j));
                } else {
                    // For i != j, if pre.combiner_has(i) was true, then post.combiner_has(i) is also true
                    // (since post.elems == pre.elems and post.idx = j + 1, if i >= j + 1 then i > j)
                    // If pre.combiner_has(i) was false, then pre.request_stored(i) || pre.response_stored(i)
                    // must have been true (from pre.waiting_inv), and these are unchanged.
                }
            }
        }
    };

    // request_stored_inv
    assert(forall|i: nat| #[trigger] post.request_stored(i) ==>
        post.client_waiting(i)
        && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && post.slots.index(i)) by {
        assert forall|i: nat| #[trigger] post.request_stored(i) implies
            post.client_waiting(i)
            && post.requests.index(i).rid == post.clients.index(i).get_Waiting_rid()
            && post.slots.index(i) by {
            assert(post.request_stored(i) == pre.request_stored(i));
            assert(post.client_waiting(i) == pre.client_waiting(i));
            assert(post.requests.index(i) == pre.requests.index(i));
            assert(post.clients.index(i) == pre.clients.index(i));
            assert(post.slots.index(i) == pre.slots.index(i));
        }
    };

    // response_stored_inv
    assert(forall|i: nat| #[trigger] post.response_stored(i) ==>
        post.client_waiting(i)
        && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
        && !post.slots.index(i)) by {
        assert forall|i: nat| #[trigger] post.response_stored(i) implies
            post.client_waiting(i)
            && post.responses.index(i).rid == post.clients.index(i).get_Waiting_rid()
            && !post.slots.index(i) by {
            assert(post.response_stored(i) == pre.response_stored(i));
            assert(post.client_waiting(i) == pre.client_waiting(i));
            assert(post.responses.index(i) == pre.responses.index(i));
            assert(post.clients.index(i) == pre.clients.index(i));
            assert(post.slots.index(i) == pre.slots.index(i));
        }
    };

    // combiner_has_inv
    assert(forall|i: nat| #[trigger] post.combiner_has(i) ==>
        post.client_waiting(i)
        && post.slots.index(i)
        && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
        && !post.request_stored(i)) by {
        assert forall|i: nat| #[trigger] post.combiner_has(i) implies
            post.client_waiting(i)
            && post.slots.index(i)
            && post.combiner_rid(i) == post.clients.index(i).get_Waiting_rid()
            && !post.request_stored(i) by {
            // post.combiner_has(i) = i >= (j+1) && post.elems[i].is_Some()
            // pre.combiner_has(i) = i >= j && pre.elems[i].is_Some()
            // Since post.elems == pre.elems and post.combiner_has(i) is true:
            //   i >= (j+1) which implies i >= j
            //   So pre.combiner_has(i) is also true
            assert(pre.combiner_has(i));
            // Therefore, all properties hold from pre.combiner_has_inv
        }
    };
}

