    //   But from pre.waiting_inv and pre.combiner_has(j) being false,
    //   we have pre.request_stored(j) || pre.response_stored(j)
    //   And since request/response stored are unchanged, post.request_stored(j) || post.response_stored(j)

    // Prove the invariant holds for all i
    assert forall|i: nat| #[trigger] post.client_waiting(i) implies
        post.request_stored(i) || post.response_stored(i) || post.combiner_has(i) by {
        // All fields except combiner are unchanged
        assert(post.client_waiting(i) == pre.client_waiting(i));
